public class ProbeProtectedInternalPartialTests
{
    [Fact]
    public async Task NestedProtectedInternalDoesNotRequirePartial()
    {
        string input = @"
using MessagePack;

public class Outer
{
    [MessagePackObject]
    protected internal class Inner
    {
        [Key(0)]
        public int Value { get; set; }
    }
}
";

        await new VerifyCS.Test { TestCode = input }.RunAsync();
    }
}

