using MessagePack;
using Xunit;

[MessagePackObject]
public class ProbeDuplicateKeyType
{
    [Key(0)]
    public int A { get; set; }

    [Key(0)]
#pragma warning disable MsgPack005
    public int B { get; set; }
#pragma warning restore MsgPack005
}

public class ProbeDuplicateKeyGenerationTests
{
    [Fact]
    public void DuplicateKeyGeneratedTypeRoundTrips()
    {
        var value = new ProbeDuplicateKeyType { A = 1, B = 2 };
        byte[] bytes = MessagePackSerializer.Serialize(value, MessagePackSerializerOptions.Standard);
        ProbeDuplicateKeyType result = MessagePackSerializer.Deserialize<ProbeDuplicateKeyType>(bytes, MessagePackSerializerOptions.Standard);
        Assert.Equal(1, result.A);
        Assert.Equal(2, result.B);
    }
}
